<?php declare(strict_types=1);namespace StudPulse\Security;use StudPulse\Config;use StudPulse\Bars\{BarsJournal,BarsOfficialAdapter};use StudPulse\Database\DB;use StudPulse\Domain\JournalScope;use StudPulse\Http\ApiError;use StudPulse\Http\Request;final class Auth{public const JOURNAL_READ='journal:read';public const JOURNAL_WRITE='journal:write';public const JOURNAL_GROUP_PREFIX='journal:group:';public const SCOPES=['profile:read','schedule:read','grades:read','attendance:read','homework:read','homework:write','materials:read','materials:write','notices:read','notifications:read','settings:read','settings:write','notes:read','notes:write',self::JOURNAL_READ,self::JOURNAL_WRITE,'headman:write'];public?array$user=null;public?array$session=null;public?array$apiToken=null;public?array$membership=null;private string$rawSession='';private?array$verifiedJournal=null;public function __construct(Request$r,bool$resolve=true){if(!$resolve){return;}$header=$r->header('Authorization');if($header!==''){if(!preg_match('/^Bearer (sp_[A-Za-z0-9_-]{43})$/',$header,$m)){throw new ApiError(401,'INVALID_TOKEN','Недействительный API-токен');}$this->apiToken=DB::one('SELECT * FROM api_tokens WHERE token_hash=? AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP(6)',[Crypto::hash($m[1])]);if(!$this->apiToken){throw new ApiError(401,'INVALID_TOKEN','Токен отозван или истёк');}$this->user=DB::one("SELECT * FROM users WHERE id=? AND status='active'",[$this->apiToken['user_id']]);DB::run('UPDATE api_tokens SET last_used_at=UTC_TIMESTAMP(6) WHERE id=?',[$this->apiToken['id']]);}elseif(isset($_COOKIE['sp_session'])){$this->rawSession=(string)$_COOKIE['sp_session'];$idle=(int)Config::get('SESSION_IDLE_DAYS','7');$this->session=DB::one('SELECT * FROM user_sessions WHERE session_token_hash=? AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP(6) AND last_seen_at>DATE_SUB(UTC_TIMESTAMP(6), INTERVAL '.$idle.' DAY)',[Crypto::hash($this->rawSession)]);if($this->session){$this->user=DB::one("SELECT * F