QUIRED','Недостаточно полномочий токена');}}public function browserOnly(bool$recent=false):void{$this->require();if(!$this->session||$this->apiToken){throw new ApiError(403,'BROWSER_SESSION_REQUIRED','Нужна браузерная сессия');}if($recent&&strtotime($this->session['authenticated_at'].' UTC')<time()-900){throw new ApiError(403,'REAUTH_REQUIRED','Для этого действия повторите вход');}}public function verifyCsrf(Request$r):void{if($this->apiToken){return;}if(!$this->session||!hash_equals($this->csrf()??'',$r->header('X-CSRF-Token'))){throw new ApiError(403,'CSRF','Проверка безопасности не пройдена');}self::origin($r);}public static function origin(Request$r):void{$origin=$r->header('Origin');if($origin===''||!in_array($origin,[rtrim(Config::get('APP_BASE_URL'),'/'),rtrim(Config::get('FRONTEND_ORIGIN'),'/')],true)){throw new ApiError(403,'ORIGIN','Недопустимый источник запроса');}}public function group():array{$this->require();if(!$this->membership){throw new ApiError(403,'GROUP_UNVERIFIED','Доступ появится после проверки учебной группы');}return$this->membership;}public function headman():array{$m=$this->group();if(!$this->canManageGroupContent()){throw new ApiError(403,'HEADMAN_REQUIRED','Нужна подтверждённая роль старосты');}return$m;}public function canManageGroupContent():bool{return($this->membership['role']??null)==='headman';}public function journal(bool$allowToken=false):array{if($allowToken&&$this->apiToken){$this->require(self::JOURNAL_READ);}else{$this->browserOnly();}if($this->verifiedJournal!==null){return$this->verifiedJournal;}if(Config::get('BARS_PROVIDER_MODE')==='official'){if(($this->user['provider']??'')==='bars'){$grant=(new BarsOfficialAdapter($this,microtime(true)+10))->verifiedJournal();if($grant!==null){if($this->apiToken){$this->require(self::JOURNAL_GROUP_PREFIX.$grant['externalGroup']);}return$this->verifiedJournal=JournalScope::resolve($grant);}}}throw new ApiError(403,'JOURNAL_ROLE_REQUIRED','БАРС открывает журнал старосте и ответственным з